package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import jakarta.servlet.http.*;
import java.math.BigInteger;
import java.util.Set;
import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
/** N05-only mTLS transport. Caller locators never substitute for signed lease/input authority. */
@RestController
@ConditionalOnProperty(name="medical.professional-runtime.source-verifier-enabled",havingValue="true",matchIfMissing=false)
public final class TaskSourceVerifierRuntimeController{
 private final TaskSourceVerifierDispatchJournal dispatches;private final TaskSourceVerifierReviewRecovery completed;
 private final org.springframework.jdbc.core.JdbcTemplate db;private final com.ruoyi.medical.identity.ServiceCertificateIdentity identities;private final ProfessionalRuntimeObservations observations;private final TaskSourceVerifierHostBootstrap bootstrap;private final TaskSourceVerifierHostOrchestrator host;private final TaskSourceVerifierSupervisorGate gate;private final TaskSourceVerifierInvocationBridge models;private final TaskSourceVerifierSchema schema;
 public TaskSourceVerifierRuntimeController(TaskSourceVerifierDispatchJournal dispatches,TaskSourceVerifierReviewRecovery completed,TaskSourceVerifierHostBootstrap bootstrap,TaskSourceVerifierHostOrchestrator host,TaskSourceVerifierSupervisorGate gate,TaskSourceVerifierInvocationBridge models,TaskSourceVerifierSchema schema,@org.springframework.beans.factory.annotation.Qualifier("sourceVerifierRuntimeObservations")ProfessionalRuntimeObservations observations,@org.springframework.beans.factory.annotation.Qualifier("masterDataSource")javax.sql.DataSource data,@org.springframework.beans.factory.annotation.Qualifier("formalRunServiceIdentity")com.ruoyi.medical.identity.ServiceCertificateIdentity identities){this.dispatches=dispatches;this.completed=completed;this.db=new org.springframework.jdbc.core.JdbcTemplate(data);this.identities=identities;this.observations=observations;this.bootstrap=bootstrap;this.host=host;this.gate=gate;this.models=models;this.schema=schema;}
 @PostMapping("/internal/v1/source-verifier-runtime/open-workflow") public JsonNode openWorkflow(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"reference","dispatch");var mapper=workflowMapper();return dispatches.openWorkflow(q,mapper.treeToValue(b.required("reference"),com.ruoyi.medical.workflow.WorkflowProtocol.Reference.class),mapper.treeToValue(b.required("dispatch"),com.ruoyi.medical.workflow.WorkflowProtocol.Dispatch.class),completed);}
 @PostMapping("/internal/v1/source-verifier-runtime/completed-original") public JsonNode completedOriginal(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"reference","dispatch");var mapper=workflowMapper();return dispatches.completed(q,mapper.treeToValue(b.required("reference"),com.ruoyi.medical.workflow.WorkflowProtocol.Reference.class),mapper.treeToValue(b.required("dispatch"),com.ruoyi.medical.workflow.WorkflowProtocol.Dispatch.class),completed).orElseThrow(()->new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE));}
 private static com.fasterxml.jackson.databind.ObjectMapper workflowMapper(){return com.fasterxml.jackson.databind.json.JsonMapper.builder().enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_NULL_FOR_PRIMITIVES,com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_MISSING_CREATOR_PROPERTIES).build();}

 @PostMapping("/internal/v1/source-verifier-runtime/admit") public JsonNode admit(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id");var h=handle(q,b);var start=host.admit(q,h);var out=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("session_id",text(start,"session_id")).put("admission","CURRENT").put("isolation_receipt_id",text(start,"isolation_receipt_id")).put("supervision_sha256",text(start,"supervision_sha256"));out.set("binding",start.required("binding"));return out;}
 @PostMapping("/internal/v1/source-verifier-runtime/heartbeat") public JsonNode heartbeat(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id");var handle=handle(q,b);handle.heartbeat();return handle.execute(s->{if(!"OPEN".equals(s.state()))deny();var out=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("session_id",s.sessionId()).put("admission","CURRENT");out.set("binding",s.binding());return out;});}
 @PostMapping("/internal/v1/source-verifier-runtime/bridge") public JsonNode bridge(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id","method","route","body","idempotency_key","model_request_observation");return models.forward(q,handle(q,b),text(b,"session_id"),text(b,"method"),text(b,"route"),nullable(b.required("body")),b.required("idempotency_key").isNull()?null:text(b,"idempotency_key"),nullable(b.required("model_request_observation")));}
 @PostMapping("/internal/v1/source-verifier-runtime/supervisor-plan") public JsonNode plan(HttpServletRequest q,HttpServletResponse r)throws Exception{return gate.read(q,body(q,r),false);}
 @PostMapping("/internal/v1/source-verifier-runtime/supervisor-admission") public JsonNode gate(HttpServletRequest q,HttpServletResponse r)throws Exception{return gate.read(q,body(q,r),true);}
 @PostMapping("/internal/v1/source-verifier-runtime/close-admission") public JsonNode close(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);original(q,b);return observations.close(q,b);}
 @PostMapping("/internal/v1/source-verifier-runtime/failure") public JsonNode failure(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);original(q,b);return observations.failure(q,b);}
 @PostMapping("/internal/v1/source-verifier-runtime/status") public JsonNode status(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id");var row=original(q,b);var out=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("session_id",text(b,"session_id")).put("admission",row.get("admission_state").toString()).put("process_exit","NOT_ATTESTED_BY_HOST_OBSERVATION");out.set("binding",b.required("binding"));return out;}
 private java.util.Map<String,Object> original(HttpServletRequest q,JsonNode b)throws Exception{var binding=ProfessionalRuntimeObservations.jsonBinding(b.required("binding"));var peer=identities.require(q);var rows=db.queryForList("SELECT admission_state,canonical_start,start_sha256 FROM professional_runtime_session WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? AND lease_generation=? AND session_id=? AND input_sha256=? AND envelope_sha256=? AND service_uri=? AND certificate_sha256=? AND trust_revision=? LIMIT 2",binding.tenant_id(),binding.run_id(),binding.step_id(),binding.action_id(),binding.lease_generation(),text(b,"session_id"),binding.input_sha256(),binding.step_envelope_sha256(),peer.serviceUri(),peer.certificateSha256(),peer.trustRevision());if(rows.size()!=1)deny();var row=rows.get(0);var start=schema.read(row.get("canonical_start").toString());if(!schema.hash(start).equals(row.get("start_sha256"))||!"N05".equals(text(start,"node_kind"))||!"TASK".equals(text(start,"purpose"))||!FormalTaskNodeAuthority.sameEvidence(b.required("binding"),start.required("binding")))deny();return row;}
 private TaskSourceVerifierHostAccess.Handle handle(HttpServletRequest q,JsonNode b)throws Exception{var h=bootstrap.open(q,ProfessionalRuntimeObservations.jsonBinding(b.required("binding")));h.prepare(e->{dispatches.requireWorkerLaunch(e);if(!text(b,"session_id").equals(e.sessionId())||!FormalTaskNodeAuthority.sameEvidence(b.required("binding"),e.binding()))deny();return null;});return h;}
 private JsonNode body(HttpServletRequest q,HttpServletResponse r)throws Exception{r.setHeader("Cache-Control","no-store");if(q.getQueryString()!=null||q.getHeader("Origin")!=null||q.getHeader("Sec-Fetch-Site")!=null)deny();return schema.read(q.getInputStream().readNBytes(TaskSourceVerifierSchema.MAXIMUM_BYTES+1));}
 private static JsonNode nullable(JsonNode n){return n.isNull()?null:n;}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())deny();return n.required(k).textValue();}private static void closed(JsonNode n,String... f){ProfessionalRuntimeObservations.closed(n,Set.of(f));}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
